package edu.pe.cibertec.saibm.usuario.application.usecase; import java.time.*; import java.util.*; import edu.pe.cibertec.saibm.usuario.application.port.in.*; import edu.pe.cibertec.saibm.usuario.application.port.out.*; import edu.pe.cibertec.saibm.usuario.domain.event.*; import edu.pe.cibertec.saibm.usuario.domain.exception.UserNotFoundException; import edu.pe.cibertec.saibm.usuario.domain.model.*; public class UserService implements UserUseCase {private final UserStorePort store;private final UserEventPublisher events;private final Clock clock;public UserService(UserStorePort s,UserEventPublisher e,Clock c){store=s;events=e;clock=c;}public UserView create(UserCommand c,String corr){var email=c.email().trim().toLowerCase(Locale.ROOT);if(store.byEmail(email).isPresent())throw new IllegalStateException("Email already exists");var p=UserProfile.create(UUID.randomUUID(),c.firstName(),c.lastName(),c.dni(),email,null,now());store.save(p);event(UserEventType.CREATED,p,corr);return view(p);}public UserView find(UUID id,Actor a){var p=load(id);if(a==null||(!a.admin()&&(!a.owns(id)||!p.active())))throw new UserNotFoundException(id);return view(p);}public List<UserView> list(String q,Actor a){if(a==null||!a.admin())throw new UserNotFoundException("list");return store.search(q==null?"":q).stream().map(this::view).toList();}public UserView update(UUID id,UserCommand c,Actor a,String corr){var p=load(id);authorize(p,a);var email=c.email().trim().toLowerCase(Locale.ROOT);store.byEmail(email).filter(x->!x.id().equals(id)).ifPresent(x->{throw new IllegalStateException("Email already exists");});var n=p.update(c.firstName(),c.lastName(),c.dni(),email,now());store.save(n);event(UserEventType.CHANGED,n,corr);return view(n);}public void deactivate(UUID id,Actor a,String corr){var p=load(id);authorize(p,a);if(p.active()){var n=p.deactivate(now());store.save(n);event(UserEventType.DEACTIVATED,n,corr);}}public void reactivate(UUID id,Actor a,String corr){var p=load(id);if(a==null||!a.admin())throw new UserNotFoundException(id);if(!p.active()){var n=p.reactivate(now());store.save(n);event(UserEventType.REACTIVATED,n,corr);}}private UserProfile load(UUID id){return store.find(id).orElseThrow(()->new UserNotFoundException(id));}private void authorize(UserProfile p,Actor a){if(a==null||(!a.admin()&&(!a.owns(p.id())||!p.active())))throw new UserNotFoundException(p.id());}private Instant now(){return clock.instant();}private void event(String type,UserProfile p,String corr){events.publish(new UserEvent(UUID.randomUUID(),type,p.id(),now(),corr==null?"":corr,"usuario-service"));}private UserView view(UserProfile p){return new UserView(p.id(),p.firstName(),p.lastName(),p.dni(),p.email(),p.active(),p.legacyUserId());}}
